def parse_json(text: str) -> object:
    n = len(text)
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < n and text[pos] in ' \t\n\r':
            pos += 1

    def parse_string():
        nonlocal pos
        pos += 1  # skip opening "
        chars = []
        while True:
            if pos >= n:
                raise ValueError("unterminated string")
            c = text[pos]
            if c == '"':
                pos += 1
                return ''.join(chars)
            if c == '\\':
                pos += 1
                if pos >= n:
                    raise ValueError("unterminated string")
                ec = text[pos]
                pos += 1
                if ec == '"':
                    chars.append('"')
                elif ec == '\\':
                    chars.append('\\')
                elif ec == '/':
                    chars.append('/')
                elif ec == 'b':
                    chars.append('\b')
                elif ec == 'f':
                    chars.append('\f')
                elif ec == 'n':
                    chars.append('\n')
                elif ec == 'r':
                    chars.append('\r')
                elif ec == 't':
                    chars.append('\t')
                elif ec == 'u':
                    if pos + 4 > n:
                        raise ValueError("invalid \\u escape")
                    hx = text[pos:pos + 4]
                    for ch in hx:
                        if ch not in '0123456789abcdefABCDEF':
                            raise ValueError("invalid \\u escape")
                    pos += 4
                    cp = int(hx, 16)
                    if 0xD800 <= cp <= 0xDBFF:
                        if pos + 6 > n:
                            raise ValueError("lone high surrogate")
                        if text[pos] != '\\' or text[pos + 1] != 'u':
                            raise ValueError("lone high surrogate")
                        hx2 = text[pos + 2:pos + 6]
                        for ch in hx2:
                            if ch not in '0123456789abcdefABCDEF':
                                raise ValueError("invalid \\u escape")
                        cp2 = int(hx2, 16)
                        if not (0xDC00 <= cp2 <= 0xDFFF):
                            raise ValueError("invalid surrogate pair")
                        pos += 6
                        combined = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00)
                        chars.append(chr(combined))
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError("lone low surrogate")
                    else:
                        chars.append(chr(cp))
                else:
                    raise ValueError("invalid escape sequence")
            elif ord(c) < 0x20:
                raise ValueError("unescaped control character in string")
            else:
                chars.append(c)
                pos += 1

    def parse_number():
        nonlocal pos
        start = pos
        if pos < n and text[pos] == '-':
            pos += 1
        if pos >= n:
            raise ValueError("invalid number")
        if text[pos] == '0':
            pos += 1
            if pos < n and text[pos] in '0123456789':
                raise ValueError("leading zero")
        elif text[pos] in '123456789':
            while pos < n and text[pos] in '0123456789':
                pos += 1
        else:
            raise ValueError("invalid number")
        has_frac = False
        if pos < n and text[pos] == '.':
            pos += 1
            has_frac = True
            if pos >= n or text[pos] not in '0123456789':
                raise ValueError("invalid number")
            while pos < n and text[pos] in '0123456789':
                pos += 1
        has_exp = False
        if pos < n and text[pos] in 'eE':
            pos += 1
            has_exp = True
            if pos < n and text[pos] in '+-':
                pos += 1
            if pos >= n or text[pos] not in '0123456789':
                raise ValueError("invalid number")
            while pos < n and text[pos] in '0123456789':
                pos += 1
        num_str = text[start:pos]
        if has_frac or has_exp:
            return float(num_str)
        return int(num_str)

    stack = []

    while True:
        skip_ws()
        if pos >= n:
            raise ValueError("unexpected end of input")

        c = text[pos]
        value = None

        if c == '[':
            pos += 1
            skip_ws()
            if pos < n and text[pos] == ']':
                pos += 1
                value = []
            else:
                stack.append(['array', []])
                continue
        elif c == '{':
            pos += 1
            skip_ws()
            if pos < n and text[pos] == '}':
                pos += 1
                value = {}
            else:
                stack.append(['object', {}, None])
                continue
        elif c == '"':
            value = parse_string()
        elif c == 't':
            if text[pos:pos + 4] == 'true':
                pos += 4
                value = True
            else:
                raise ValueError("invalid literal")
        elif c == 'f':
            if text[pos:pos + 5] == 'false':
                pos += 5
                value = False
            else:
                raise ValueError("invalid literal")
        elif c == 'n':
            if text[pos:pos + 4] == 'null':
                pos += 4
                value = None
            else:
                raise ValueError("invalid literal")
        elif c in '-0123456789':
            value = parse_number()
        else:
            raise ValueError("unexpected character")

        while True:
            if not stack:
                skip_ws()
                if pos < n:
                    raise ValueError("trailing content")
                return value
            frame = stack[-1]
            if frame[0] == 'array':
                frame[1].append(value)
                skip_ws()
                if pos < n and text[pos] == ',':
                    pos += 1
                    break
                elif pos < n and text[pos] == ']':
                    pos += 1
                    value = frame[1]
                    stack.pop()
                    continue
                else:
                    raise ValueError("expected ',' or ']'")
            else:
                if frame[2] is None:
                    if not isinstance(value, str):
                        raise ValueError("object key must be a string")
                    frame[2] = value
                    skip_ws()
                    if pos >= n or text[pos] != ':':
                        raise ValueError("expected ':'")
                    pos += 1
                    break
                else:
                    key = frame[2]
                    frame[2] = None
                    if key in frame[1]:
                        raise ValueError("duplicate key")
                    frame[1][key] = value
                    skip_ws()
                    if pos < n and text[pos] == ',':
                        pos += 1
                        break
                    elif pos < n and text[pos] == '}':
                        pos += 1
                        value = frame[1]
                        stack.pop()
                        continue
                    else:
                        raise ValueError("expected ',' or '}'")
